func vectorNorm(vector []float64) float64 {
	var sum float64
	for _, value := range vector {
		sum += value * value
	}
	return math.Sqrt(sum)
}

// Косинус между запросом и вектором прямо из блоба, без промежуточного среза
// float64 на каждого кандидата. Норма запроса приходит посчитанной снаружи:
// прежний код пересчитывал её заново для каждого кандидата, то есть тратил на
// это треть всей арифметики поиска. Формула та же, что в cosineSimilarity,
// поэтому и оценки, и порядок выдачи совпадают с прежними.
func cosineSimilarityFromBlob(query []float64, queryNorm float64, blob []byte) (float64, error) {
	if len(blob)%4 != 0 {
		return 0, fmt.Errorf("embedding vector blob length is not divisible by 4: %d", len(blob))
	}
	if len(blob)/4 != len(query) {
		return 0, fmt.Errorf("embedding dimensions mismatch: %d != %d", len(query), len(blob)/4)
	}
	var dot, candidateNorm float64
	for i, value := range query {
		component := float64(math.Float32frombits(binary.LittleEndian.Uint32(blob[i*4:])))
		dot += value * component
		candidateNorm += component * component
	}
	if queryNorm == 0 || candidateNorm == 0 {
		return 0, nil
	}
	return dot / (queryNorm * math.Sqrt(candidateNorm)), nil
}
